    "question_fr": "Une solution aqueuse d'iodure de potassium (KI) se dissocie complètement et a une concentration massique Cm = 83 g/L. Quelle est la pression osmotique exercée par cette solution par rapport à son solvant à 20 °C ? Données : M(K) = 39 g/mol, M(I) = 127 g/mol, R = 0,082 atm·L·mol⁻¹·K⁻¹, T(K) = °C + 273.",
    "question_en": "An aqueous solution of potassium iodide (KI) dissociates completely and has a mass concentration of Cm = 83 g/L. What is the osmotic pressure exerted by this solution relative to its solvent at 20°C? Given: M(K) = 39 g/mol, M(I) = 127 g/mol, R = 0.082 atm·L·mol⁻¹·K⁻¹, °C = K − 273.",
